<div class="page-head"><div><div class="section-kicker">Operating costs</div><h1>Expenses</h1><p class="lede">Review business spending and keep supporting receipts with each record.</p></div><button class="btn btn-primary" type="button" data-open-expense>Add expense</button></div>
<section class="expense-summary"><div><small>Selected period</small><b><?= e(date('d M',strtotime($from))) ?> – <?= e(date('d M Y',strtotime($to))) ?></b></div><div><small>Total expenses</small><strong><?= money($total) ?></strong></div><div><small>Records</small><b><?= number_format(count($expenses)) ?></b></div></section>
<form method="get" action="<?= e(url('expenses')) ?>" class="expense-filter"><label><span>From</span><input type="date" name="from" value="<?= e($from) ?>"></label><label><span>To</span><input type="date" name="to" value="<?= e($to) ?>"></label><button class="btn btn-primary btn-sm" type="submit">Apply dates</button><a class="btn btn-ghost btn-sm" href="<?= e(url('expenses')) ?>">This month</a></form>
<?php if(!$expenses): ?><div class="inline-empty"><b>No expenses in this period</b><span>Adjust the dates or record the first business expense.</span><button class="btn btn-primary" type="button" data-open-expense>Add expense</button></div><?php else: ?><div class="expense-directory"><?php foreach($expenses as $x): ?><article class="expense-record"><span class="expense-category-icon" aria-hidden="true"><?= e(strtoupper(substr($x['category'],0,1))) ?></span><div class="expense-record-main"><b><?= e($x['description']) ?></b><small><?= e(ucfirst($x['category'])) ?><?= $x['is_recurring']?' · Recurring':'' ?> · <?= e(date('d M Y',strtotime($x['expense_date']))) ?></small></div><div><small>Recorded by</small><b><?= e($x['user_name']?:'System') ?></b></div><?php if($x['receipt_file']): ?><a class="btn btn-ghost btn-sm" target="_blank" href="<?= e(url('expenses/'.$x['id'].'/receipt')) ?>">View receipt ↗</a><?php else: ?><span class="expense-no-receipt">No receipt</span><?php endif; ?><strong><?= money($x['amount']) ?></strong><?php if(Auth::isAdmin()): ?><button class="btn btn-danger-ghost btn-sm" type="button" data-delete-expense="<?= (int)$x['id'] ?>" data-expense-label="<?= e($x['description']) ?>">Delete</button><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
<dialog class="workflow-dialog expense-dialog" id="expense-dialog"><form method="post" action="<?= e(url('expenses')) ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="workflow-dialog-head"><span aria-hidden="true">＋</span><div><div class="section-kicker">New expense</div><h2>Record business spending</h2></div></div><div class="expense-presets" aria-label="Category presets"><?php foreach($categories as $category): ?><button type="button" data-expense-category="<?= e($category) ?>"><?= e(ucfirst($category)) ?></button><?php endforeach; ?></div><label class="field"><span>Description</span><input type="text" name="description" required maxlength="255" placeholder="e.g. Shop rent — September"></label><div class="form-row"><label class="field"><span>Amount (KSh)</span><input type="number" name="amount" step="0.01" min="0.01" required></label><label class="field"><span>Date</span><input type="date" name="expense_date" value="<?= e(date('Y-m-d')) ?>" required></label></div><label class="field"><span>Category</span><select name="category"><?php foreach($categories as $category): ?><option value="<?= e($category) ?>"><?= e(ucfirst($category)) ?></option><?php endforeach; ?></select></label><label class="field"><span>Receipt attachment <em>Optional</em></span><input type="file" name="receipt" accept="image/jpeg,image/png,application/pdf"><small>JPG, PNG, or PDF up to 5 MB.</small></label><label class="dialog-confirm-check"><input type="checkbox" name="is_recurring" value="1"><span>This expense normally repeats.</span></label><div class="workflow-dialog-actions"><button class="btn btn-ghost" type="button" data-close-expense>Cancel</button><button class="btn btn-primary" type="submit">Save expense</button></div></form></dialog>
<?php if(Auth::isAdmin()): ?><dialog class="workflow-dialog" id="delete-expense-dialog"><form method="post" data-delete-expense-form><?= csrf_field() ?><div class="workflow-dialog-head danger"><span>!</span><div><div class="section-kicker">Audit-controlled deletion</div><h2>Delete expense?</h2></div></div><p class="dialog-copy" data-delete-expense-copy></p><label class="field"><span>Reason for deletion</span><textarea name="delete_reason" required maxlength="500" rows="3" placeholder="Duplicate entry, incorrect amount…"></textarea></label><div class="workflow-dialog-actions"><button class="btn btn-ghost" type="button" data-close-delete-expense>Keep expense</button><button class="btn btn-danger" type="submit">Delete with reason</button></div></form></dialog><?php endif; ?>
<script>(function(){var dialog=document.getElementById('expense-dialog');document.querySelectorAll('[data-open-expense]').forEach(function(b){b.addEventListener('click',function(){dialog.showModal();});});document.querySelector('[data-close-expense]').addEventListener('click',function(){dialog.close();});document.querySelectorAll('[data-expense-category]').forEach(function(b){b.addEventListener('click',function(){dialog.querySelector('select[name="category"]').value=b.dataset.expenseCategory;dialog.querySelector('input[name="description"]').focus();});});<?php if(Auth::isAdmin()): ?>var dd=document.getElementById('delete-expense-dialog'),df=dd.querySelector('form');document.querySelectorAll('[data-delete-expense]').forEach(function(b){b.addEventListener('click',function(){df.action='<?= e(url('expenses')) ?>/'+b.dataset.deleteExpense+'/delete';dd.querySelector('[data-delete-expense-copy]').textContent='“'+b.dataset.expenseLabel+'” will leave the active expense ledger. The reason remains in the audit trail.';dd.showModal();});});document.querySelector('[data-close-delete-expense]').addEventListener('click',function(){dd.close();});<?php endif; ?>})();</script>
<?php if(($_GET['add']??'')==='1'): ?><script>document.getElementById('expense-dialog').showModal();</script><?php endif; ?>
